170	pub async fn run_stdio_server(codex_home: &AbsolutePathBuf) -> anyhow::Result<()> {
171	    let backend = LocalMemoriesBackend::from_codex_home(codex_home);
172	    tokio::fs::create_dir_all(backend.root())
173	        .await
174	        .with_context(|| format!("create memories root at {}", backend.root().display()))?;
175	    MemoriesMcpServer::new(backend)
176	        .serve((tokio::io::stdin(), tokio::io::stdout()))
177	        .await?
178	        .waiting()
179	        .await?;
180	    Ok(())
181	}
