224	fn backend_error_to_mcp(err: MemoriesBackendError) -> McpError {
225	    match err {
226	        MemoriesBackendError::InvalidPath { .. }
227	        | MemoriesBackendError::NotFile { .. }
228	        | MemoriesBackendError::EmptyQuery => McpError::invalid_params(err.to_string(), None),
229	        MemoriesBackendError::Io(_) => McpError::internal_error(err.to_string(), None),
230	    }
231	}
